preConditionHook:
// THE SECOND failed swing-extreme breakout within the window -- Brooks's
// second attempt to reverse, the one more likely to work.
//
// The counted event is FailedSwingBreakoutReversal's own condition, inlined,
// over the pivot scan inlined from rules/SwingHigh.json (the measured
// primitive: STRICTLY beyond the `strength` NEWER bars, AT OR BEYOND the
// `strength` OLDER ones, confirmation lag exactly `strength`, -1 sentinel
// guarded, deepest bar swingLookback - 1 + strength, el_gt/el_ge because the
// comparisons carry the relational tolerance).
//
// NOT CountIF. The merged pseudocode counts the event over the last lookback
// bars, but CountIF's condition is a true SERIES whose offsets shift per
// counted bar, so counting this event would evaluate SwingLow(...)[i] at
// every offset in the window -- and the LAGGED read of a swing function has
// no register row. A persistent age counter says the same thing with measured
// words only, and it is how the corpus already handles second-entry logic
// (HighLowBarCount's settled counter).
//
// The age is advanced BEFORE the test and reset AFTER it, so at the moment of
// the test lowEvAge is the number of bars since the PREVIOUS event -- 1 at
// the earliest -- which reproduces "some earlier bar i in 1..lookback". The
// locals start at 0 / false exactly as the EasyLanguage variables do, so the
// twins agree through warm-up as well: no event can be claimed before one has
// actually printed.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)strength;
pivWindow = (int)swingLookback;
pivotHighBar = -1;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool ok = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivStrength; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) { pivotHighBar = j; break; }
}
pivotLowBar = -1;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool ok = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivStrength; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) { pivotLowBar = j; break; }
}
evLow = false;
evHigh = false;
if (pivotLowBar != -1) {
    evLow = el_lt(low[0], low[pivotLowBar]) && el_gt(close[0], low[pivotLowBar]);
}
if (pivotHighBar != -1) {
    evHigh = el_gt(high[0], high[pivotHighBar]) && el_lt(close[0], high[pivotHighBar]);
}
if (haveLowEv) lowEvAge = lowEvAge + 1;
if (haveHighEv) highEvAge = highEvAge + 1;
secondLow = evLow && haveLowEv && el_le((double)lowEvAge, lookback);
secondHigh = evHigh && haveHighEv && el_le((double)highEvAge, lookback);
if (evLow) { haveLowEv = true; lowEvAge = 0; }
if (evHigh) { haveHighEv = true; highEvAge = 0; }
